import unittest


class TestParseNestedParens(unittest.TestCase):

    def test_basic_example(self):
        self.assertEqual(parse_nested_parens('(()()) ((())) () ((())()())'), [2, 3, 1, 3])

    def test_single_group(self):
        self.assertEqual(parse_nested_parens('(()())'), [2])

    def test_simple_parens(self):
        self.assertEqual(parse_nested_parens('()'), [1])

    def test_deeply_nested(self):
        self.assertEqual(parse_nested_parens('((()))'), [3])
        self.assertEqual(parse_nested_parens('(((())))'), [4])

    def test_multiple_groups(self):
        self.assertEqual(parse_nested_parens('() (()) ((()))'), [1, 2, 3])

    def test_empty_string(self):
        self.assertEqual(parse_nested_parens(''), [])

    def test_multiple_spaces_between_groups(self):
        self.assertEqual(parse_nested_parens('()   (())  ()'), [1, 2, 1])

    def test_leading_trailing_spaces(self):
        self.assertEqual(parse_nested_parens('  () (())  '), [1, 2])

    def test_unbalanced_input_still_returns_max_depth(self):
        # Function counts max depth reached even if unbalanced
        self.assertEqual(parse_nested_parens('(()'), [2])

    def test_result_is_list_of_ints(self):
        result = parse_nested_parens('() (())')
        self.assertIsInstance(result, list)
        self.assertTrue(all(isinstance(x, int) for x in result))


